#include <stdint.h>

typedef struct {
    volatile uint32_t KR;
    volatile uint32_t PR;
    volatile uint32_t RLR;
    volatile uint32_t SR;
} IWDG_TypeDef;

#define IWDG_BASE   0x40003000UL
#define IWDG        ((IWDG_TypeDef *)IWDG_BASE)

void delay(void)
{
    for (volatile uint32_t i = 0; i < 3000000; i++);
}

void IWDG_Init(void)
{
    /* 1. Enable IWDG and unlock PR/RLR */
    IWDG->KR = 0x5555;

    /* 2. Prescaler = /32 */
    IWDG->PR = 3;

    /* 3. Reload value */
    IWDG->RLR = 1000;

    /* 4. Start watchdog */
    IWDG->KR = 0xCCCC;
}

void IWDG_Refresh(void)
{
    /* Reload watchdog counter */
    IWDG->KR = 0xAAAA;
}

int main(void)
{
    IWDG_Init();

    while (1)
    {
        delay();
        IWDG_Refresh();   // idha miss panna board reset aagidum
    }
}
